def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]

    def runs(line, color):
        out_runs = []
        i = 0
        while i < len(line):
            if line[i] != color:
                i += 1
                continue
            j = i
            while j + 1 < len(line) and line[j + 1] == color:
                j += 1
            if j - i + 1 >= 2:
                out_runs.append((i, j))
            i = j + 1
        return out_runs

    # Find the matching colored bars on opposite grid edges.
    candidates = []
    for color in counts:
        if color == background:
            continue
        top, bottom = runs(grid[0], color), runs(grid[-1], color)
        if top and bottom:
            candidates.append((sum(b-a+1 for a,b in top)+sum(b-a+1 for a,b in bottom), 'h', color, top, bottom))
        left = runs([grid[r][0] for r in range(h)], color)
        right = runs([grid[r][-1] for r in range(h)], color)
        if left and right:
            candidates.append((sum(b-a+1 for a,b in left)+sum(b-a+1 for a,b in right), 'v', color, left, right))
    if not candidates:
        return out
    _, orient, wall, first_runs, second_runs = max(candidates, key=lambda x: x[0])
    seeds = [(r,c) for r in range(h) for c in range(w)
             if grid[r][c] != background and grid[r][c] != wall
             and not (r == 0 or r == h-1 or c == 0 or c == w-1)]
    if not seeds:
        return out
    seed_color = grid[seeds[0][0]][seeds[0][1]]

    if orient == 'h':
        a0, a1 = first_runs[0]
        b0, b1 = second_runs[0]
        # The bars define a horizontal offset between their matching spans.
        for r,c in seeds:
            out[r][c] = 4
            if a0 <= c <= a1:  # seed aligned with the top bar
                for rr in range(0, r):
                    if out[rr][c] != wall:
                        out[rr][c] = seed_color
                cc = c + (b0 - a0)
                if 0 <= cc < w:
                    for rr in range(h):
                        if out[rr][cc] != wall:
                            out[rr][cc] = seed_color
            elif b0 <= c <= b1:  # seed aligned with the bottom bar
                cc = c + (a0 - b0)
                if 0 <= cc < w:
                    for rr in range(h):
                        if out[rr][cc] != wall:
                            out[rr][cc] = seed_color
    else:
        a0, a1 = first_runs[0]  # left-edge row interval
        b0, b1 = second_runs[0] # right-edge row interval
        for r,c in seeds:
            out[r][c] = 4
            if a0 <= r <= a1:  # seed aligned with the left bar
                for cc in range(c):
                    if out[r][cc] != wall:
                        out[r][cc] = seed_color
                rr = r + (b0 - a0)
                if 0 <= rr < h:
                    for cc in range(w):
                        if out[rr][cc] != wall:
                            out[rr][cc] = seed_color
            elif b0 <= r <= b1:  # seed aligned with the right bar
                for cc in range(c+1, w):
                    if out[r][cc] != wall:
                        out[r][cc] = seed_color
                rr = r + (a0 - b0)
                if 0 <= rr < h:
                    for cc in range(w):
                        if out[rr][cc] != wall:
                            out[rr][cc] = seed_color
    return out

